      // can take part in the spatial join. Project to the same CRS as the OSM
      // layers so distances are comparable.
      geometryColumns: {
        latColumnName: "Latitude",
        longColumnName: "Longitude",
        coordinateFormat: COORDINATE_FORMAT,
      },
    });
